"""
Sliding-window rate limiter for POST /api/chat/* endpoints.

Configuration:
  RATE_LIMIT_RPM  (env, default 10) - max requests per minute per client IP
"""

import json
import os
import time
from collections import deque

_WINDOW_SECONDS = 60


def _get_limit() -> int:
    try:
        return int(os.environ.get("RATE_LIMIT_RPM", "10"))
    except (ValueError, TypeError):
        return 10


class _SlidingWindow:
    """Per-IP sliding window request counter."""

    def __init__(self, limit: int):
        self._limit = limit
        self._windows: dict[str, deque] = {}

    def check_and_record(self, ip: str) -> tuple[bool, int]:
        """Return (allowed, retry_after_seconds). Records the hit only if allowed."""
        now = time.time()
        window = self._windows.setdefault(ip, deque())
        # Evict timestamps that have fallen outside the current window
        while window and now - window[0] >= _WINDOW_SECONDS:
            window.popleft()
        if len(window) >= self._limit:
            retry_after = int(_WINDOW_SECONDS - (now - window[0])) + 1
            return False, max(1, retry_after)
        window.append(now)
        return True, 0


class ChatRateLimitMiddleware:
    """ASGI middleware: rate-limits POST /api/chat/* by client IP.

    Other methods and paths are passed through untouched.
    Returns HTTP 429 with {"error": "rate_limit_exceeded", "retry_after": <s>}
    when the limit is exceeded.
    """

    def __init__(self, app, rpm: int | None = None):
        self.app = app
        limit = rpm if rpm is not None else _get_limit()
        self._limiter = _SlidingWindow(limit)

    async def __call__(self, scope, receive, send):
        if scope["type"] == "http":
            method = scope.get("method", "")
            path = scope.get("path", "")
            if method == "POST" and path.startswith("/api/chat/"):
                ip = self._client_ip(scope)
                allowed, retry_after = self._limiter.check_and_record(ip)
                if not allowed:
                    body = json.dumps(
                        {"error": "rate_limit_exceeded", "retry_after": retry_after}
                    ).encode()
                    await send({
                        "type": "http.response.start",
                        "status": 429,
                        "headers": [
                            (b"content-type", b"application/json"),
                            (b"content-length", str(len(body)).encode()),
                            (b"retry-after", str(retry_after).encode()),
                        ],
                    })
                    await send({
                        "type": "http.response.body",
                        "body": body,
                        "more_body": False,
                    })
                    return
        await self.app(scope, receive, send)

    @staticmethod
    def _client_ip(scope) -> str:
        """Extract client IP, preferring X-Forwarded-For when present."""
        headers = dict(scope.get("headers", []))
        forwarded = headers.get(b"x-forwarded-for", b"").decode().strip()
        if forwarded:
            return forwarded.split(",")[0].strip()
        client = scope.get("client")
        return client[0] if client else "unknown"

