import pytest
from fastapi import FastAPI
from fastapi.testclient import TestClient

from routers.rate_limit import ChatRateLimitMiddleware, _SlidingWindow, _get_limit


def _make_app(rpm: int = 10) -> FastAPI:
    app = FastAPI()
    app.add_middleware(ChatRateLimitMiddleware, rpm=rpm)

    @app.post("/api/chat/prompt")
    async def chat_prompt():
        return {"ok": True}

    @app.post("/api/chat/abort")
    async def chat_abort():
        return {"ok": True}

    @app.get("/api/chat/stream/test")
    async def chat_stream():
        return {"ok": True}

    @app.get("/health")
    async def health():
        return {"ok": True}

    return app


def test_requests_under_limit_pass():
    client = TestClient(_make_app(rpm=10), raise_server_exceptions=False)
    for i in range(10):
        resp = client.post("/api/chat/prompt")
        assert resp.status_code == 200, f"Request {i+1} unexpectedly failed"


def test_11th_request_rejected():
    client = TestClient(_make_app(rpm=10), raise_server_exceptions=False)
    for _ in range(10):
        client.post("/api/chat/prompt")
    resp = client.post("/api/chat/prompt")
    assert resp.status_code == 429
    body = resp.json()
    assert body["error"] == "rate_limit_exceeded"
    assert isinstance(body["retry_after"], int)
    assert body["retry_after"] >= 1


def test_429_response_shape():
    client = TestClient(_make_app(rpm=10), raise_server_exceptions=False)
    for _ in range(10):
        client.post("/api/chat/prompt")
    resp = client.post("/api/chat/prompt")
    assert resp.status_code == 429
    body = resp.json()
    assert set(body.keys()) >= {"error", "retry_after"}
    assert body["error"] == "rate_limit_exceeded"
    assert "retry-after" in resp.headers


def test_rate_resets_after_window():
    app = _make_app(rpm=10)
    client = TestClient(app, raise_server_exceptions=False)
    base = 1_000_000.0

    with patch("routers.rate_limit.time") as mock_time:
        mock_time.time.return_value = base
        for _ in range(10):
            assert client.post("/api/chat/prompt").status_code == 200
        assert client.post("/api/chat/prompt").status_code == 429

        # Advance past the 60-second window
        mock_time.time.return_value = base + 61.0
        assert client.post("/api/chat/prompt").status_code == 200


def test_get_routes_not_rate_limited():
    client = TestClient(_make_app(rpm=2), raise_server_exceptions=False)
    for _ in range(5):
        assert client.get("/api/chat/stream/test").status_code == 200
    for _ in range(5):
        assert client.get("/health").status_code == 200


def test_non_chat_post_not_rate_limited():
    app = _make_app(rpm=2)

    @app.post("/other/endpoint")
    async def other():
        return {"ok": True}

    client = TestClient(app, raise_server_exceptions=False)
    for _ in range(5):
        assert client.post("/other/endpoint").status_code == 200


def test_per_ip_isolation():
    limiter = _SlidingWindow(limit=2)
    assert limiter.check_and_record("1.1.1.1")[0] is True
    assert limiter.check_and_record("1.1.1.1")[0] is True
    assert limiter.check_and_record("1.1.1.1")[0] is False
    assert limiter.check_and_record("2.2.2.2")[0] is True


