    client = TestClient(_make_app(rpm=10), raise_server_exceptions=False)
    for _ in range(5):
        assert client.post("/api/chat/prompt").status_code == 200
    for _ in range(5):
        assert client.post("/api/chat/abort", json={}).status_code == 200
    # 11th across both endpoints
